create or replace function bank_fee_detail(p_fee_id bigint)returns jsonb language sql stable security definer set search_path=public as $$select jsonb_build_object('header',to_jsonb(f)||jsonb_build_object('bankName',b.bank_name,'accountNumber',ba.account_number,'currencyCode',c.currency_code,'subsidiaryName',s.name,'expenseAccountNumber',ca.account_number,'expenseAccountName',ca.account_name),'impact',coalesce((select jsonb_agg(jsonb_build_object('accountNumber',a.account_number,'accountName',a.account_name,'debit',jl.debit,'credit',jl.credit,'debitLocal',jl.debit_fx,'creditLocal',jl.credit_fx,'note',jl.note)order by jl.journal_line_id)from journal_line jl join chart_accounts a using(account_id)where jl.journal_id=f.journal_id),'[]'::jsonb))from bank_fee f join bank_account ba using(bank_account_id)join banks b using(bank_id)join currencies c on c.currency_id=f.currency_id join subsidiaries s on s.subsidiary_id=f.subsidiary_id join chart_accounts ca on ca.account_id=f.expense_account_id where f.fee_id=p_fee_id and f.subsidiary_id=bank_fee_active_subsidiary()$$;
create or replace function delete_bank_fee(p_fee_id bigint)returns jsonb language plpgsql security definer set search_path=public,pg_temp as $$declare f bank_fee%rowtype;begin select*into f from bank_fee where fee_id=p_fee_id and subsidiary_id=bank_fee_active_subsidiary()for update;if f.fee_id is null then raise exception 'No se encontró la comisión.';end if;update bank_account set balance=balance+f.amount where bank_account_id=f.bank_account_id;delete from bank_transaction where transaction_id=f.transaction_id;delete from bank_fee where fee_id=f.fee_id;delete from journal_support where journal_id=f.journal_id;delete from journal_line where journal_id=f.journal_id;delete from journal where journal_id=f.journal_id;delete from "transaction"where transaction_id=f.transaction_id;return jsonb_build_object('success',true,'number',f.fee_number);end$$;
create or replace function update_bank_fee(p_fee_id bigint,p_payload jsonb)returns jsonb language plpgsql security definer set search_path=public,pg_temp as $$begin if not exists(select 1 from bank_fee where fee_id=p_fee_id and subsidiary_id=bank_fee_active_subsidiary())then raise exception 'No se encontró la comisión.';end if;perform delete_bank_fee(p_fee_id);return save_bank_fee(p_payload);end$$;
revoke all on function bank_fee_detail(bigint),update_bank_fee(bigint,jsonb),delete_bank_fee(bigint)from public,anon;grant execute on function bank_fee_detail(bigint),update_bank_fee(bigint,jsonb),delete_bank_fee(bigint)to authenticated;notify pgrst,'reload schema';
